window.TERRA_RACES={"meta":{"title":"泰拉种族专题","date":"2026-11-04","revision":"documentary-expanded-20261104","entries":32,"scope":"《大地巡旅》第四章实际列出的32个具名种族主条目；不是全部游戏、联动族群或萨卡兹支系的穷尽名录。","printedPages":"079—106","sourceFile":"TERRA+A+JOURNEY.txt","sourceBytes":1214927,"sourceSha256":"00515b3aa0bd38983c4f785210b35865afa1441409765c81e31bb1c40c997f1b","sourceKind":"用户提供的官方设定集TXT转录；不是原版影印校样","method":"原创转述；区分作者论述、凯尔希批注、传说与个体见闻；不按耳角外观猜种族，不从族群统计反推个人年龄、寿命或具体技艺。","characters":14258},"overview":[{"title":"名称怎样形成","body":"《大地巡旅》把种族名称放在人类社会的发展中讨论。早期聚落、征服、人口迁徙与地方认同，参与塑造了今日的分类；相似的外貌不总意味着相同的历史，沿用同一称谓的人也可能拥有不同文化。本专题先交代能够核实的来源与变迁，再讨论当代生活，不为材料没有记载的族群补造一条完整年代轴。"},{"title":"先民与神民怎样理解","body":"先民、神民是泰拉历史与族群认识中的分类，不能直接等同于一个人的国籍、阶层或道德。书中以“供养—保护”模型解释部分古代社会，凯尔希批注又提醒，并非所有国家都经历过神民统治。梦魔远征和乌萨斯起义动摇了旧秩序，种族平等观念随后发展，但感染者所承受的不平等并未因此消失。"},{"title":"兽主、兽亲与族群不是一套分类","body":"兽主和其分离出的兽亲，并不是泰拉人先民、神民分类的另两个普通分支。书中批注以佩洛、狼之主等例子解释相互接触，也提醒读者：看到形似某种生物的个体，不能据外观确定其身份。专题与人物档案的关联，优先依据游戏本体公开的种族字段；未公开的记录继续保留未公开。"},{"title":"萨卡兹与王庭的范围","body":"萨卡兹是具有漫长共同历史的复杂族群称谓，王庭氏族只是其中一部分。书中还提到鬼、阿纳萨等非王庭氏族，而当代个体常具有混合血缘。本专题在萨卡兹篇下提供这些相关公开档案，卡片同时保留游戏原有登记，不把政治组织、血缘支系和个人身份合并成同一层级。"}],"entries":[{"id":"ursus","name":"乌萨斯","en":"Ursus","summary":"从北迁的族群到以族名命名的帝国，种族归属与国民身份在这段历史中交织。","relatedRegions":["ursus","kazimierz","kjerag","yan"],"profileNames":["乌萨斯"],"relatedNames":[],"sourceLines":[948,954],"sections":[{"title":"北迁与帝国建立","period":"早期迁徙至31年建国","body":"乌萨斯的族名早于乌萨斯帝国。设定集把其主要人口向北集中的过程，追溯到追随骏鹰迁居的时代：一批乌萨斯随黎博利神民前往北地，在当地建立定居点，却处在骏鹰的统治之下。后来梦魔远征打击了旧王国，伊戈尔领导的起义又改变了政权归属。今日族群分布集中于北方，是这些迁徙与政治变动逐步形成的结果。\n\n帝国之外同样有乌萨斯居民。卡西米尔、谢拉格、萨尔贡北部和炎国等地的群体，各有不同的生活环境与地方历史。书中提到的毛色差别，包括炎境内的黑白相间分支，属于族群内部的外貌差异。\n\n北地长期严寒，以及较强的体力和耐力，构成乌萨斯常被强调的群体形象。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·乌萨斯（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第948—954行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"族名与国民认同","period":"帝国形成以后","body":"帝国建立以后，同一个词逐渐承担两层身份。一个人说自己是乌萨斯，可能在陈述种族，也可能是在表达对国家的归属；两者重合时，称谓会同时指向身体来源和国民认同。帝国境外自称乌萨斯的人，也未必都登记为这一种族。\n\n设定集特别指出，乌萨斯较早形成了明确的国民概念。这种认同把共同国家、历史记忆和政治忠诚纳入称呼，使帝国可以要求不同种族的居民认同同一个祖国。相应地，生来属于乌萨斯种族的人。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·乌萨斯（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第948—954行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·乌萨斯（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第948—954行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"feline","name":"菲林","en":"Feline","summary":"分布广泛、内部差异显著的庞大族群，维多利亚的迁徙史只是其中一条支线。","relatedRegions":["victoria","sargon","kjerag"],"profileNames":["菲林"],"relatedNames":[],"sourceLines":[955,960],"sections":[{"title":"广泛分布与迁徙","period":"古代迁徙至现代混居","body":"菲林与佩洛、黎博利同属人口众多、分布广泛的族群。尖耳、长尾和敏锐感官是常见特征，但书中同时保留了圆耳、短尾等少数形态。古代人曾以一组外貌特征概括大量个体，因而菲林从名称形成时起，就包含彼此有差别的支系。\n\n维多利亚的族群史能够说明这种差异怎样继续积累。德拉克统治时期，当地已经生活着多种居民；后来随阿斯兰进入的追随者与旧居民通婚，其后裔成为维多利亚菲林人口的重要来源。一个现代家庭与萨尔贡的远亲联系，可以来自这段迁移史。\n\n庞大人口和适应不同环境的能力，使菲林继续出现在各地城市与聚落中。但设定集没有替所有分支写出一致的出发地和迁徙日期。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·菲林（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第955—960行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"名称与地方身份","period":"族群分类逐渐细化以后","body":"耳尾除了参与感知和身体活动，也被用于表达情绪。某些菲林瞳孔在光照变化时会改变形态，这些细节构成书中对日常身体经验的观察。\n\n阿斯兰获得独立称谓以后，其他群体也曾试图为自己争取新名字，但并非每种尝试都留下了持久、广泛接受的分类。书中以此说明，族名的沿用既与身体差别有关，也取决于权力、历史记忆和社会承认。菲林这个大类继续存在。\n\n因此，同为菲林的人物可以在语言、社会位置和政治目标上相距甚远。王国臣民、荒野来客与都市劳动者共享某些生理特点，却分别在各自的生活制度中形成经验。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·菲林（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第955—960行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·菲林（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第955—960行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"aslan","name":"阿斯兰","en":"Aslan","summary":"阿斯兰的独立称谓与征服、王权和族群自我认知的变化相连。","relatedRegions":["sargon","victoria"],"profileNames":["阿斯兰"],"relatedNames":[],"sourceLines":[961,966],"sections":[{"title":"征服与独立称谓","period":"部落时代的阿斯兰征服","body":"阿斯兰人口稀少，主要家系见于萨尔贡和维多利亚。设定集把其独立名称的形成放在征服史中：从生理分类看，他们属于菲林；从行政登记和社会承认看，阿斯兰又长期被当作独立族群。独立称谓的形成与征服者要求其他群体承认自身地位的行为相连。\n\n阿斯兰统治者传播了关于族群边界的认识，也促使其他外貌相近的群体进一步区分自身。后来研究能够为许多新分类找到生理差异，书中却没有为阿斯兰从菲林中独立提供同样的生物学理由。这一不对称，说明种族名称在不同历史阶段可能承担不同的政治功能。\n\n较强的平均体力为古代征战提供了条件，封地与追随者又支撑起统治。封地、追随者、继承制度与宫廷联盟，才把个体能力变成能够世代维持的统治位置；相关过程须与两国沿革合读。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·阿斯兰（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第961—966行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"萨尔贡与维多利亚的家系","period":"阿斯兰向维多利亚迁徙以后","body":"生活在萨尔贡与维多利亚的阿斯兰，被书中明确视为同一种族内部的不同家族。两地家系后来形成不同的王权关系。\n\n在萨尔贡，阿斯兰家系与万王之王、帕夏及宫廷竞争相连；部分支系离开之后，进入维多利亚，并在当地取得皇室地位。家族转移带来了新的政治继承问题，也改变了旧统治者与地方贵族的关系。\n\n现代人物继承的既有显赫姓氏，也有王位空缺、流亡和政治追索留下的责任。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·阿斯兰（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第961—966行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·阿斯兰（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第961—966行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"perro","name":"佩洛","en":"Perro","summary":"从古代宽泛称呼到现代分类，佩洛的历史也记录了人们如何重新划分相似族群。","relatedRegions":["bolivar","sargon","sami","higashi"],"profileNames":["佩洛"],"relatedNames":[],"sourceLines":[967,977],"sections":[{"title":"古代称呼与分化","period":"族群命名逐渐细化的时期","body":"佩洛从萨尔贡到萨米、从玻利瓦尔到东国都有分布，人口规模也很大。玻利瓦尔是书中列出的重要聚居地区。如此广阔的分布并非一场统一迁徙的结果，书中也没有给出全族共同建国、共同离乡的一条时间线。\n\n在远古时代，若干外貌近似的群体曾被统称为佩洛。后来，生理研究与对族群边界认识的变化，使鲁珀、沃尔珀、瑞柏巴等称谓逐渐被区分出来。阿斯兰征服所传播的分类观念也参与了这一过程。\n\n佩洛内部同时包含先民与神民的多支群体。书中列出的奎尔莎、刻俄柏洛斯等分支，大多与其他佩洛共同生活，外人未必容易辨认。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·佩洛（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第967—977行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"家族传统与生活环境","period":"长期形成的聚落文化及现代生活","body":"传统佩洛聚落常把全体成员视作同一个大家族，维系邻里和亲属关系因而具有实际生活意义。书中把友善待人、重视和谐的文化倾向与这种聚落结构联系起来。\n\n玻利瓦尔的部分佩洛还对军方使用的猎犬表现出熟悉与厌恶并存的反应。作者正文记录相关传言时保留了证据不足的判断；批注则从兽主与兽亲的机制提出进一步解释。正文与批注分别保存了观察记录和进一步解释。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·佩洛（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第967—977行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·佩洛（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第967—977行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"lupo","name":"鲁珀","en":"Lupo","summary":"叙拉古的家族政治深刻影响了鲁珀文化，兽主与人类的关系又构成另一层历史。","relatedRegions":["siracusa","victoria","ursus"],"profileNames":["鲁珀"],"relatedNames":[],"sourceLines":[978,987],"sections":[{"title":"叙拉古与家族秩序","period":"古老聚落至家族城邦形成","body":"鲁珀主要与叙拉古相联系，在其他国家也有分布。其生理形态与佩洛相近，但独立称谓形成得较早，家族文化又强化了社会辨识。生活在叙拉古的鲁珀，可以通过共同染色的尾巴、耳尖记号等方式表示家族归属，标记由此成为公开辨认成员的方法。\n\n在家族势力控制的地区，共同身份同时划出了内外界线。同一家族强调团结，不同家族之间却可能长期敌对。食物、土地和安全资源的争夺，以及各地狼群带来的生存压力，被设定集用来解释这种文化形成的条件。\n\n由此形成的等级、保护与服从关系，会持续进入现代城市生活。一个人物是否接受家族安排、能否离开原有关系，须结合其具体处境判断。并非每位鲁珀都在大家族中长大，离开叙拉古的人也可能拥有完全不同的生活经验。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·鲁珀（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第978—987行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"兽主影响与个人选择","period":"家族文化延续至现代","body":"作者正文把狼群视为塑造当地社会的重要力量，批注进一步说明狼之主之间的争斗，以及被选作代理者的獠牙。部分被兽主选中的人物，以“獠牙”身份参与狼主之间的竞争。\n\n日常交流也能体现家族训练留下的差别。部分上层家庭教导子女控制耳尾动作，避免让情绪轻易外露；与此同时，手势仍是常见表达方式。未受这类教育的人并不因此缺少鲁珀身份，习惯晃动尾巴的个体也不该被视为分类上的反例。\n\n书中这两类观察分别涉及长期环境压力和日常身体规训。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·鲁珀（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第978—987行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·鲁珀（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第978—987行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"vulpo","name":"沃尔珀","en":"Vulpo","summary":"从斥候与信使的古老职业传统，到跨族开放的尾巴护理活动，沃尔珀的文化随环境变化。","relatedRegions":["siracusa","higashi","sargon"],"profileNames":["沃尔珀"],"relatedNames":[],"sourceLines":[988,994],"sections":[{"title":"辨认、分布与职业传统","period":"古代部落至现代佣兵和信使组织","body":"沃尔珀在许多地方容易被误认为佩洛，统计人口时也因此存在困难。设定集没有据不可靠的统计给出一个精确总量，而只概括其在多数地区所占比例较低。\n\n书中记述沃尔珀反应敏捷、身体柔韧，在复杂环境中感知危险的能力受到重视。古代部落挑选斥候与信使时，已有人被视作适合这些职责；米诺斯相关英雄史诗也留下了这类记忆。现代佣兵与信使组织中仍能见到沃尔珀，但职业延续还依赖训练与个人选择。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·沃尔珀（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第988—994行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"分支与尾部文化","period":"长期形成的地方传统","body":"沃尔珀内部有不同先民和神民分支。九尾沃尔珀主要见于东国，是书中最常被提及的一支；关于其与上层家族的联系，作者没有掌握足以展开的细节。\n\n在叙拉古，梳理蓬松尾毛发展为明确的社交礼仪，家庭聚会也是展示护理成果的场合。后来，这种习惯延伸出接纳其他种族参加的尾巴护理比赛。参赛者按主办方命题，在限定时间内完成造型，把私人仪容转成公开的技艺与审美活动。\n\n从聚会礼节到开放比赛，可以看到文化习惯怎样随着交流扩大。它不只提供一种外貌印象，也涉及人们如何准备会面、建立交往与参加城市娱乐。不同地区的沃尔珀未必都遵循同样礼节。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·沃尔珀（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第988—994行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·沃尔珀（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第988—994行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"reproba","name":"瑞柏巴","en":"Reproba","summary":"以萨尔贡为主要生活地区，荒地经验、女性主导的大家族和军旅传统相互联系。","relatedRegions":["sargon","bolivar"],"profileNames":["瑞柏巴"],"relatedNames":[],"sourceLines":[995,1002],"sections":[{"title":"从古老称呼到独立分类","period":"部落时代至分类观念形成","body":"瑞柏巴人口较少，主要分布在萨尔贡。其祖先曾被放在古老佩洛概念之内，一些生活传统又使他们在周围人眼中显得特殊。随着旧传统的一部分被放弃、族群分类逐步改变，瑞柏巴才作为独立名称延续下来。名称出现得较晚。\n\n长期荒地居住留下了适应沙漠和邻近区域的经验。大家族以女性为主导，有的家族接近百人，并推举名义上的女性大家长；维持团结、纪律和共同生活，是这些组织的重要事务。\n\n瑞柏巴曾向萨尔贡军队提供士兵，部分古老传说也记载女战士反抗梦魔远征。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·瑞柏巴（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第995—1002行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"荒地家庭与走向外地","period":"长期形成的生活传统及近代迁徙","body":"古老生活方式使瑞柏巴祖先出现在萨尔贡的一些恐怖故事中，也使他们不时被拿来与萨卡兹比较。书中记录了对此不同的态度：有人忌讳这类说法，也有人并不在意。\n\n近代以来，越来越多瑞柏巴走出祖辈居住的区域，把荒地经验用于野外考察、特殊牲畜饲养等专业工作。迁居者将聚落内传授的知识带入新的雇佣、研究与贸易关系。\n\n外地人仍可能把他们统称为佩洛，这种误认反映了信息传播的局限。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·瑞柏巴（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第995—1002行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·瑞柏巴（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第995—1002行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"liberi","name":"黎博利","en":"Liberi","summary":"羽毛特征下包含许多差异显著的群体，国别、迁徙与职业往往比一个总称更能解释个人经历。","relatedRegions":["columbia","iberia","laterano","ursus"],"profileNames":["黎博利"],"relatedNames":[],"sourceLines":[1003,1009],"sections":[{"title":"广泛称谓与迁徙","period":"古代分布至哥伦比亚移民潮","body":"黎博利这一称谓囊括了多种体表生羽的神民与先民，因此人口众多、支系复杂。哥伦比亚、伊比利亚与拉特兰都有大量黎博利居民，其他地区也不罕见。不同支系的羽毛分布、体貌与地方传统并不一致，羽毛只能说明某些共同身体特征。\n\n骏鹰是其中著名的神民分支，兼具黎博利的羽毛与库兰塔式尾部特征，曾建立北方王国。它的政权后来被乌萨斯起义推翻，而黎博利这个大类继续存在。一个支系的统治兴亡，与遍布各地的整个族群是不同尺度的历史。\n\n身体较轻、中等身高等记述是书中的一般观察。设定集并未把鸟类外形直接等同于飞行能力，人物的作战与生活方式仍需以实际经历和公开能力记录为准。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·黎博利（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1003—1009行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"地方文化与分类争论","period":"现代多族社会","body":"哥伦比亚建国后吸纳各地移民，大批黎博利也在这一过程中迁入。寻找新生活的机会是重要原因，总统马克·麦克斯的公众形象也参与了联邦的吸引力。书中引用的移民调查，记录的是移民对目的地的认识。\n\n移居者进入的城市、行业与社群并不相同，因而难以概括全族共同文化。有学者希望继续拆分黎博利，另一些人则反对把文化差异直接当作生物分类依据。这场争论反映了一个长期问题：同一个大类既包含身体相近的人，也包含历史经历相距甚远的社会。\n\n在相关人物的故事里，国教、科研机构、地方劳动与家族关系往往比共同羽毛特征更直接地影响行动。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·黎博利（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1003—1009行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·黎博利（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1003—1009行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"cautus","name":"卡特斯","en":"Cautus","summary":"从应对天灾的屯堡大家庭，到矿业联合体，聚居和互助始终参与塑造卡特斯的生活。","relatedRegions":["rim","ursus"],"profileNames":["卡特斯","卡特斯/奇美拉"],"relatedNames":[],"sourceLines":[1010,1016],"sections":[{"title":"屯堡与联合家庭","period":"部落时代的雷姆必拓","body":"卡特斯在雷姆必拓及周边地区最为集中。当地先民面对天灾和相对有限的个体体力，以群居、共同劳动和联合家庭维持生活。他们开凿半地下屯堡，在周围种植根茎作物、寻找矿脉，把居住、防灾和生产安排在同一片社区中。\n\n联合家庭承担了人员互助和内部关系的组织作用。家庭成员数目可以很多，日常劳动与照顾并不只由一个小家庭独立完成。年轻人外出探险、到其他地方建立家庭也常得到支持，因为新的出发能够减轻原聚落的人口压力，并延续不同社区间的联系。\n\n长耳、灵敏听觉与较快反应是书中记述的常见身体特征。居民仍要依靠集体劳作应对天灾。屯堡制度的重要性，在于居民怎样把共同劳动、住房和家庭关系组织起来。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·卡特斯（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1010—1016行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"互助传统的延续与改变","period":"结晶时代以来","body":"结晶时代的源石工业发展后，传统屯堡的生活开始转入更大规模的矿业网络。卡特斯打开社区边界，组建矿业联合体，把原来由聚落承担的生产与协作事务，延伸到厂区、运输和跨社区组织之中。\n\n设定集因此把联合体同时视为经济与社会组织：它经营矿业，也承接社区互助、生产安排和集体认同。面对维多利亚在围栏事件中的压力，参与者能够依托这些关系持续组织抵抗。温和的日常交往形象，并未使他们在涉及家园和自治时放弃共同立场。\n\n从屯堡到联合体的变化，使雷姆必拓的城市、矿区和离乡者仍保留着相互关联的历史。现代卡特斯既可能继续参与矿业，也可能进入其他行业；每位人物的家庭与工作，应放在这条长期转变中理解。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·卡特斯（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1010—1016行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·卡特斯（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1010—1016行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"kuranta","name":"库兰塔","en":"Kuranta","summary":"平原迁徙、骑士家族与梦魔远征，共同构成库兰塔分布和军事文化的历史。","relatedRegions":["kazimierz","sargon"],"profileNames":["库兰塔"],"relatedNames":[],"sourceLines":[1017,1023],"sections":[{"title":"平原生活与远征后的分散","period":"古代定居至梦魔远征以后","body":"库兰塔祖先在中北部平原定居后，曾长期以随季节和环境移动的方式生活。面对随时可能出现的突袭，聚落需要迅速集结与行动，广泛习武因而成为军事传统。后来骑士团文化所依凭的体能、机动与组织习惯，在这种平原生活中已有早期基础。\n\n梦魔可汗的远征又使一批库兰塔离开原有平原，参与跨越大地的长期征战。远征结束以后，后裔分散在不同地区，形成了今日跨国分布的来源之一。\n\n天马与梦魔是其中最著名的神民血脉。天马王权在战争和政变后失去王位，转为骑士贵族；梦魔则在远征失败后散居。这两条支系的历史在同一场征服中交会，后续却分别进入不同家系与地方社会。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·库兰塔（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1017—1023行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"家族、长骑与现代骑士","period":"骑士政权建立至竞技商业化","body":"游牧生活中，住处可以随季节改变，家人却是长期相处的固定成员。家族秩序因而承担了维持团体的作用，长骑作为领袖负责协调。现代卡西米尔的移动城市和竞技产业改变了大量居民的生活，骑士协会仍保留相关长骑制度，旧身份由此继续产生实际政治与资格影响。\n\n战争机动也在现代装备与训练下发生变化。设定集转述监正会的公开报告，记下银枪天马追上老式乌萨斯战舰、强行登舰的战例，保存了一支现代骑士团的机动与作战记录。\n\n临光家族、征战骑士和竞技骑士的故事，分别展示这些传统如何被继承、改造和争议。读到家族继任与赛场资格时，需要同时看到名义头衔、家庭责任和现实制度，不将骑士称号只理解为一项个人荣誉。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·库兰塔（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1017—1023行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·库兰塔（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1017—1023行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"forte","name":"丰蹄","en":"Forte","summary":"常被简化成力量象征的丰蹄，也保留着哲学、农耕与因地制宜的运输传统。","relatedRegions":["minos","yan","sargon"],"profileNames":["丰蹄"],"relatedNames":[],"sourceLines":[1024,1030],"sections":[{"title":"米诺斯与思想传统","period":"古代城邦时期","body":"丰蹄在米诺斯的族群构成中占重要位置，在炎国、萨尔贡等平原地区也广泛分布。\n\n古代思想家费那拉底是书中举出的例子。她与来自萨尔贡的一位菲林女性讨论哲学，两人没有留下完整著作与体系，相关问题仍在此后被不断重述。相关问题在后来仍被不断重述，成为当地思想交流的一部分。\n\n米诺斯的英雄崇拜、公共辩论和城邦文化，为这些活动提供了社会空间。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·丰蹄（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1024—1030行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"农耕、运输与迁移","period":"长期形成的生产生活","body":"在米诺斯之外，丰蹄常以劳动者身份进入外界记录。炎国一些丰蹄群体被认为很早就开始农耕：种植要求长期投入体力，也要求在天灾威胁下安排土地、物资和迁移。定居并未彻底取消移动需求，反而形成了围绕多块耕地来往的生活方式。\n\n关于适应崎岖地形运输车的发明，书中保留了传说性质。这类工具使人们能够更快地在耕地之间转移，兼顾地力恢复与灾害规避。它把农事、运输和避灾联系起来，也说明技术经验往往来自长期劳动中的实际问题。\n\n后来从事运输、工程或其他职业的丰蹄，各有具体受训和谋生经历。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·丰蹄（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1024—1030行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·丰蹄（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1024—1030行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"caprinae","name":"卡普里尼","en":"Caprinae","summary":"对术法和音乐的热爱与莱塔尼亚历史相连。","relatedRegions":["leithanien","sargon"],"profileNames":["卡普里尼"],"relatedNames":[],"sourceLines":[1031,1036],"sections":[{"title":"分布与术法认识","period":"长期形成的族群分布","body":"卡普里尼主要分布在莱塔尼亚及周边，也生活在其他地区。对源石技艺的较好适应性，使这一群体在外界眼中常与术师联系在一起。设定集同时明确记载，卡普里尼中也存在无法使用源石技艺的个体，平均倾向与个人能力并不总是重合。\n\n莱塔尼亚的政治文化，为理解这种社会印象提供了具体历史：施术、音乐、教育和高塔贵族的地位相互关联，相关知识通过学校与宫廷传授，成为国家组织生活的一部分。一个人的技艺表现还取决于学习、训练和所能接触的资源，而不只是种族登记。\n\n书中对精神特点与技艺适应性联系的解释，属于理论性推想。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·卡普里尼（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1031—1036行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"角的审美与不同生活","period":"地方文化延续至现代","body":"卡普里尼对角的关注，首先体现在日常审美与身体护理中。他们不只比较本族角的形态，也会讨论丰蹄、埃拉菲亚、瓦伊凡等其他族群的角。相关兴趣因此跨越族群边界，成为交往、观察与文化表达的题材。\n\n品评与展示角的活动，成为当地社交和审美的一部分。迁居其他国家、参与科研或从事普通工作的卡普里尼，也会形成所在城市与家庭的习惯。\n\n相同的种族可以在不同制度下获得很不一样的成长机会；术师之国的声望，也未必能保护每位居民免受贫困、偏见或暴力。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·卡普里尼（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1031—1036行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·卡普里尼（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1031—1036行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"elafia","name":"埃拉菲亚","en":"Elafia","summary":"萨米的迁徙与自然文化影响深远。","relatedRegions":["sami","ursus","kazimierz","leithanien"],"profileNames":["埃拉菲亚"],"relatedNames":[],"sourceLines":[1038,1055],"sections":[{"title":"萨米来源与向外迁徙","period":"早期分布至现代城市扩张","body":"设定集把许多外地埃拉菲亚群体的来源追溯到萨米。其后裔逐渐分布在乌萨斯、卡西米尔、莱塔尼亚等多林地地区，部分边远聚落仍维持游猎生活，另一些人则已进入城市。迁居带来新的职业和社会联系，也使旧日自然信仰在不同家庭中被保留、改变或淡忘。\n\n几百年前的文艺作品曾根据林地生活和分叉角，把埃拉菲亚塑造成神秘的森林之子。这种解释传播很广，却没有提供生理或历史研究的依据。对自然的亲近，更多能够在萨米的文化习惯与具体聚落生活中找到来处。\n\n因此，现代埃拉菲亚既可能保存部族传统，也可能对这些传统十分陌生。城市居民不因离开林地而失去身份，萨米信仰也并非每一个埃拉菲亚个人都必须承袭的宗教。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·埃拉菲亚（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1038—1055行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"角与地方交流传统","period":"族群成长及地方仪式","body":"书中介绍，许多埃拉菲亚的角在成长的某一阶段由皮肤覆盖，并有神经分布，能够产生触觉。角的接触因此不只是外观动作，也可能成为一种亲近、争论与情感表达。设定集以两位诗人双角相抵、合作写作的传闻，说明这一身体经验怎样被文学记住。\n\n萨米部分部族还把角理解为感知自然的媒介，有些个体的角长期保持缓慢生长与知觉。作者在这里借具体受访者的描述介绍当地观念，并没有为全部埃拉菲亚确立同样的施术能力。\n\n这些记述把身体、语言和地方信仰联系起来。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·埃拉菲亚（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1038—1055行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·埃拉菲亚（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1038—1055行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"vouivre","name":"瓦伊凡","en":"Vouivre","summary":"从阿斯兰统治下的自治领地，到护卫与佣兵传统，瓦伊凡的迁徙与政治关系相伴。","relatedRegions":["sargon","victoria"],"profileNames":["瓦伊凡"],"relatedNames":[],"sourceLines":[1064,1068],"sections":[{"title":"征服、分封与迁徙","period":"阿斯兰征服及其后","body":"瓦伊凡主要分布在萨尔贡、维多利亚及瓦伊凡联盟控制的地区。其早期政治地位与阿斯兰征服相连：被击败以后，部分部落因战力受到认可，获得北方边界的土地，领袖保有较高自治权，成员也可以担任阿斯兰护卫。领地、军事服务与保护关系由此结合。\n\n后来，一支阿斯兰家系进入维多利亚时带走部分瓦伊凡，这些追随者成为当地瓦伊凡群体的先辈。追随者随统治家族迁移，进入新地区后逐步参与当地政治与生活。\n\n书中也比较了瓦伊凡与德拉克的相似外形和平均技艺差异。两者相近，并不使其在历史中承担相同地位；具体人物的身体能力与源石技艺仍按其本人的档案记述。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·瓦伊凡（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1064—1068行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"自治领与佣兵道路","period":"近代工业化及现代生活","body":"传统部落重视年轻人的战斗与护卫训练，资质出众者有机会进入萨尔贡宫廷，其他受训者则常以雇佣作战谋生。护卫筛选、军事训练和佣兵劳动相衔接，构成书中对瓦伊凡佣兵传统来源的解释。后来有人在服役结束后留居别国，迁徙又进一步扩大。\n\n与此同时，北部领地并未永远停留在古代封赏的状态。现代部落联合修建小型移动城市，瓦伊凡联盟又尝试争取更完全的政治自主。设定集写作时，这一诉求仍与萨尔贡主权相冲突。\n\n因此，宫廷侍卫、地方居民和跨国佣兵虽共享族群背景，其工作关系和政治目标仍有区别。各人的经历，应继续追踪到雇主、部队、城市与具体委托。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·瓦伊凡（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1064—1068行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·瓦伊凡（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1064—1068行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"manticore","name":"曼提柯","en":"Manticore","summary":"萨尔贡偏远聚落保留着低调生活传统，外界的神秘传说往往掩盖了普通居民的日常。","relatedRegions":["sargon"],"profileNames":["曼提柯"],"relatedNames":[],"sourceLines":[1069,1086],"sections":[{"title":"偏远聚落与居住选择","period":"移动城市出现前后","body":"曼提柯人数少，主要生活在萨尔贡。头部两侧的膜状翅、延伸的节肢状甲壳尾和尾端刺针，是书中记述的常见身体形态；只有部分个体的尾针带有毒液。它们使曼提柯容易被外界赋予危险形象。\n\n移动城市扩大以后，许多曼提柯继续留在偏远聚落，没有随着城市化迁入同样的居住空间。低调、隐蔽和与其他社群保持距离，是当地长期保存的生活习惯。这种选择也使外界接触机会较少，历史记录因而十分有限。\n\n村落的延续说明，他们拥有自己的共同生活和定居安排。所谓神秘，首先来自双方信息与来往的不对等。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·曼提柯（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1069—1086行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"隐蔽传统与外部误解","period":"长期形成的地方文化","body":"作者曾组织研究团队拜访一处固定居住地。村长起初不愿接待，团队说明希望了解当地文化以后，村民才同意开门。书中保留下来的这次交涉，显示外来者进入社区需要具体说明目的。\n\n村长谈到族名时，把它放在非常古老的传说里；作者并没有据此确定一个早于人类的建族年份。与此同时，周边流传的食人、诅咒等故事，被书中明确视为对陌生群体的攻击性污蔑。传说与实际拜访所得，必须分别看待。\n\n从聚落走向地表城市或加入外部机构的个人，可能面对这些已有印象。其能否与他人交流、怎样建立伙伴关系，来自具体接触与长期相处，不由尾针或偏远出身预先决定。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·曼提柯（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1069—1086行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·曼提柯（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1069—1086行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"phidia","name":"斐迪亚","en":"Phidia","summary":"人口分散、缺少统一聚居模式的斐迪亚，常被文学偏见赋予缺乏依据的形象。","relatedRegions":["sargon","victoria","sami","ursus"],"profileNames":["斐迪亚"],"relatedNames":[],"sourceLines":[1087,1093],"sections":[{"title":"分散居住与外部形象","period":"长期分布至现代生活","body":"斐迪亚人口相对少，却并不只居住在一个国家。从萨米到乌萨斯、从萨尔贡到维多利亚，都能找到其居民。没有广泛集中聚居的习俗，使许多人只能通过书籍和艺术形象认识他们，外界认知因而较少来自持续的社区往来。\n\n设定集描述的主要外形是尖耳与有鳞长尾，平均身形较高、体重较轻。身体形态又被大众文学转写为瘦弱、敏感乃至情绪不稳等印象，作者对此提出异议。尤其是蛇这一别名在多种语言中带有复杂意味，称谓本身可能先于对一个人的真正了解。\n\n书中还逐项澄清了常见误认：多数斐迪亚没有毒，以双脚行走，也不会因为种族而发出蛇类的嘶声。这些说明针对的是既有传闻，不构成对某位未公开人物的医学或能力推断。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·斐迪亚（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1087—1093行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"职业经验与个人材料","period":"作者当代见闻","body":"作者以两位熟识者说明个体长期投入某项工作的经历。一位研究者尝试用彩色源石灯实现远程即时通信，后来参与谢拉格铁路建设，为线路设计信号系统。原先的技术研究由此进入实际交通设施，持续的专注也落实为具体工程。\n\n另一位受访者关注骑士竞技的结果，历时多年编成篇幅庞大的年鉴分析，并继续准备下一年度版本。她所进行的是记录、整理和分析。同一项公共活动，因此可以成为观众、研究者和作战者截然不同的经历。\n\n作者从熟识者身上观察到专注的倾向，但也承认其他族群同样有人如此。这里能够补充的是具体工作及其持续过程。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·斐迪亚（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1087—1093行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·斐迪亚（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1087—1093行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"savra","name":"萨弗拉","en":"Savra","summary":"沙漠与荒地经验构成常见生活背景，长寿者的具体经历也被传说过度放大。","relatedRegions":["sargon","rim","victoria"],"profileNames":["萨弗拉"],"relatedNames":[],"sourceLines":[1103,1107],"sections":[{"title":"荒地生活与迁居","period":"长期居住及现代人口流动","body":"萨弗拉主要生活在萨尔贡，也有群体迁居雷姆必拓。他们常见于日照充足的荒地环境；身体与尾部的鳞片、敏锐视觉和较灵活的动作，与当地狩猎及野外活动相适应。部分个体能够改变鳞片颜色，配合衣物隐入周边景物，但不是所有萨弗拉都具有相同外观或能力表现。\n\n长寿与萨尔贡出身是设定集承认的常见认识，大众故事又在此基础上塑造了狡猾老猎人的固定形象。形象反复流传，使外地人容易把一种文学角色当作整个族群。书中同时介绍生活在维多利亚的萨弗拉，显示其经历并不限于沙漠狩猎。\n\n离开原居地以后，居民仍可能继续使用荒地经验，也会进入新的城市工作和公共生活。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·萨弗拉（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1103—1107行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"寿命记述与个体差异","period":"作者记录的当代人物","body":"书中以卡拉顿的昂斯特先生提供了一则具体长寿见闻。作者记述时，这位老人已生活超过一个半世纪，在记述的前一年仍于议员岗位工作。双方关于源石工业策略的交谈，还促使作者重新考虑自己过去的一些看法。\n\n这次会面留下了年长居民参与现代政治与产业讨论的记录。\n\n可以确认的长期生活经验，应写成其亲历的事件和持续工作，而不凭种族补出一串从未记载的历史见证。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·萨弗拉（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1103—1107行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·萨弗拉（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1103—1107行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"zalak","name":"札拉克","en":"Zalak","summary":"广泛迁徙的札拉克在信使、城镇劳动和影视传播中呈现出多种生活面貌。","relatedRegions":["kazimierz","kjerag","columbia","rim"],"profileNames":["札拉克"],"relatedNames":[],"sourceLines":[1108,1118],"sections":[{"title":"广泛分布与职业变化","period":"传统迁徙至现代城市生活","body":"札拉克人口庞大、分布广泛，玻利瓦尔与雷姆必拓等地都有其居民，近代又有不少人迁往哥伦比亚。身体形态在不同群体间存在差别：有些圆耳因耳簇显得尖，北方部分居民尾毛更浓密，较温暖地区又常见不同毛发形态。\n\n听觉、反应和对气流变化的敏感，使一些札拉克进入信使职业，也能在天灾信使队伍中见到他们。要成为能够实际穿行荒野、判断灾情并传递消息的人，仍需知识、训练和路线经验，身体特点只是工作条件的一部分。\n\n广阔分布也让札拉克进入完全不同的国家制度和行业。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·札拉克（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1108—1118行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"社会印象与影视传播","period":"近代移民与1094年后的文化传播","body":"哥伦比亚影视产业兴起后，一批札拉克演员获得知名度。书中特别提到1094年的喜剧片《拜托！怎么又来了》：伯尔尼·盖利饰演的主人公出身低微，曾在思想上摇摆，最后作出决定，使传统英雄故事得到新的演绎。\n\n影片受欢迎以后，原本带有贬义、用来讥讽无用囤积的称呼，在一些地方被重新理解为为亲友作长远准备。大众娱乐因此参与了族群公共形象的改变，也吸引一些札拉克加入拓荒。随后，荒野生存的实际经验又经报刊进入城市读者的认识。\n\n电影、宣传和迁居相互影响，形成了近代社会的一段具体过程。它并不表示所有札拉克都看过同一影片。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·札拉克（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1108—1118行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·札拉克（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1108—1118行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"durin","name":"杜林","en":"Durin","summary":"分布在地下的城邦各具文化，先进技术与相对独立的社会生活并存。","relatedRegions":["durin","sargon"],"profileNames":["杜林"],"relatedNames":[],"sourceLines":[1119,1123],"sections":[{"title":"地下城邦与有限记录","period":"长久地下生活至近百年的外部研究","body":"地表文献很早就零星提到杜林，但关于其社会的较完整资料，在设定集所述近百年才逐渐积累。外界常根据较矮身材编造疾病起源的解释，书中明确否定了这种说法。缺乏接触造成的传闻，与杜林人真实的身体和生活并不是同一回事。\n\n杜林的居住单位是分布在地下的城邦，各城依靠先进技术建造并维持环境，也有保持往来的办法。不同城邦的社会形态与文化并不一致。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·杜林（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1119—1123行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"走向地表与彼此交往","period":"个别迁居及现代接触","body":"只有一部分杜林人选择来到地表。他们可以进入城市、造访聚落或参与外部工作，却很少详细说明来处。书中记录，有来客把地表社会视为值得观察的有趣对象；这是一种个别见闻，并不是所有离乡者共同签订的使命。\n\n杜林较早掌握先进建造技术，部分地表来客通过见闻和工程合作认识这些成果。\n\n地下城市的灾害、探索和迁移，又会不断改变人们怎样走向地表。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·杜林（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1119—1123行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·杜林（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1119—1123行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"cerato","name":"塞拉托","en":"Cerato","summary":"绿洲聚落的生活经验、对角的重视和羽兽饲养，构成书中记录的塞拉托文化。","relatedRegions":["sargon"],"profileNames":["塞拉托"],"relatedNames":[],"sourceLines":[1135,1139],"sections":[{"title":"绿洲生活与向外迁居","period":"萨尔贡传统聚居及近百年迁徙","body":"塞拉托原本是萨尔贡绿洲中的族群之一，近百年逐渐出现在其他地区。强健体格和奔跑能力是常见记述，但他们不像部分库兰塔那样频繁长途跋涉。书中转述的解释，把这一习惯与成年后的高大体型、体重及持续运动消耗联系起来，仍保留为当地人认可的一种说法。\n\n在绿洲生活中，角既是醒目的身体特征，也是自部落时期沿用的重要武器。其意义不只在外形好看，而在实际对抗中能承受怎样的力量。因此，塞拉托对角的珍视，形成了与其他有角族群不同的日常实践。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·塞拉托（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1135—1139行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"角与聚落日常","period":"长期形成的生活传统","body":"面对面短程冲锋、用角互相对抗，是书中记下的传统活动。这些在外人看来危险的动作，在当地也可能作为游戏与磨砺方式存在。近代有人选择给角加装护甲，旧身体实践因而又同新的制作技术相接。\n\n羽兽饲养则是另一面日常生活。绿洲中特定羽兽与塞拉托亲近，个人可能同时饲养数只，社区里也能见到老人带着羽兽散步。战斗训练、身体护理与照料动物，出现在同一聚落的生活中。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·塞拉托（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1135—1139行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·塞拉托（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1135—1139行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"anura","name":"安努拉","en":"Anura","summary":"雨林中的规划、建造协作和技艺传承，比外界对毒性的想象更接近实际生活。","relatedRegions":["sargon","bolivar"],"profileNames":["安努拉"],"relatedNames":[],"sourceLines":[1140,1155],"sections":[{"title":"雨林居住与外界接触","period":"古代聚落至现代迁居","body":"安努拉主要生活在萨尔贡和玻利瓦尔的湿润区域。人口较少，旧日聚落又常在雨林深处，外界与其持续来往的机会有限。迁入移动城市以后，一些人仍选择水道治理较好、绿化较多的居住环境，旧日生活需求在城市中得到新的安排。\n\n萨尔贡宫廷则长期把他们描绘为神秘、优雅的智者，并持续邀请雨林居民前往首都任职。这类邀请是两种社会之间实际发生的往来，也带有宫廷对于偏远族群的想象。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·安努拉（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1140—1155行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"社区协作与技艺边界","period":"长期形成的雨林生活","body":"雨林中的安努拉与阿达克利斯保持长期协作。建造新居所时，后者可以承担较重的施工劳动，前者则以村庄规划、装修等工作回报。节日期间合办游泳比赛，又使合作超出生产安排，成为共同生活的一部分。\n\n书中还记载潜行与隐身相关的技艺传承，以及少数个体控制毒性分泌物的能力。毒素并不是所有安努拉共同具有、持续失控的威胁；设定集特意澄清了外界对普通接触便会中毒的误解。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·安努拉（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1140—1155行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·安努拉（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1140—1155行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"archosauria","name":"阿达克利斯","en":"Archosauria","summary":"雨林沿河聚落的力量传统，始终同水中行动、社区竞技和地方认同相连。","relatedRegions":["sargon","durin"],"profileNames":["阿达克利斯"],"relatedNames":[],"sourceLines":[1156,1160],"sections":[{"title":"沿河聚落与提亚卡乌认同","period":"萨尔贡古老聚落时期","body":"阿达克利斯主要生活在萨尔贡东部湿润雨林，以沿河部落组织居住与活动。水中行动能力使他们能够游泳、捕猎，并从水路接近敌人；离开雨林以后，外地社会往往只注意其武力，较少理解这些能力与当地环境的长期联系。\n\n不少居民以提亚卡乌自称，强调骁勇善战的身份。书中把这一认同追溯到萨尔贡强盛时代，并记下其可能来自古代皇帝封赏的说法。它首先是一种被继承的社会称呼。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·阿达克利斯（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1156—1160行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"竞技与文化交流","period":"传统活动及近代变化","body":"尾巴在当地竞技中更多体现力量。拖拽原木是一项常见例子，参与者比较一次能够带动的数量，把日常使用的身体力量转化为节庆与竞争。相关项目并不只有一种，也不只有战斗用途。\n\n与外界交往增多以后，年轻人又发展出用尾巴争球、将球送入对方球门的新运动。外来形式经过改造进入部落生活，显示传统并非始终不变。与安努拉共同建房、参加游泳节庆，也说明当地社会的协作和娱乐并不只围绕武力高下展开。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·阿达克利斯（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1156—1160行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·阿达克利斯（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1156—1160行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"itra","name":"依特拉","en":"Itra","summary":"高寒山地的生活与谢拉格宗教文献传统，共同构成书中有限但具体的记录。","relatedRegions":["kjerag","yan","ursus","sami"],"profileNames":["依特拉"],"relatedNames":[],"sourceLines":[1161,1179],"sections":[{"title":"高寒地区的聚居","period":"长期形成的山地分布","body":"依特拉主要居于高寒山地和冰原附近，在炎国、谢拉格、乌萨斯及萨米的部分地方有分布。书中提到其外观与卡普里尼、埃拉菲亚或库兰塔可能近似，但依特拉没有角。\n\n高寒地区的长期生存经验，与部分社群保持警惕、减少对外来往的习惯相连。迁入现代城市并未使所有人立刻改变生活方式。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·依特拉（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1161—1179行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"宗教文献与现代职业","period":"谢拉格信仰传播至现代生活","body":"谢拉格的依特拉在宗教文字传承中留下了较明确的位置。书中认为，他们可能是很早开始崇拜耶拉冈德的群体之一，许多经文与典籍由其撰写、编纂。宗教的传播因而不仅依靠仪式，也依靠文本的整理与保存。\n\n这些活动把生活在不同地方的人与共同信仰联系起来，同时使部分家族和社区在知识传授中发挥作用。\n\n书中还收录了一位来自谢拉格的依特拉信使形象，由本人同意用于插图。宗教文字的整理者与从事外部交通的居民，一同进入了设定集对这一族群的记录。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·依特拉（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1161—1179行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·依特拉（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1161—1179行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"petram","name":"匹特拉姆","en":"Petram","summary":"水源附近的隐居聚落保存着独特工艺，对外接触的记录仍然有限。","relatedRegions":["yan","victoria","iberia"],"profileNames":["匹特拉姆"],"relatedNames":[],"sourceLines":[1180,1187],"sections":[{"title":"稀少记录与隐居聚落","period":"古代记载至作者走访","body":"匹特拉姆极少见，通常居住在水源丰富的地区，又较少主动进入公众视野。其外观缺少尾巴、角或鳞片等醒目标志，使外地人更难从短暂接触中辨识。设定集介绍这一分类时，已经说明学界掌握的材料并不充分。\n\n聚落却留下了实际工艺记录。古萨尔贡史料提到，他们掌握性能优异的金属材料制作方法，并拒绝向王酋交出相关知识。制作能力可以通过成品被外人认识，技术传授的边界则仍由聚落坚持，这也是书中能够说明的一种对外关系。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·匹特拉姆（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1180—1187行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"工艺传承与未解关系","period":"地方生产传统及当代交流","body":"作者走访过炎国、维多利亚及伊比利亚沿海的部分村庄，观察到当地匹特拉姆与上岸阿戈尔来往密切，有时互称同胞。此处记录的是具体交往与称谓，并没有给出足以确定两者血缘起源的结论。\n\n书中还把一些匹特拉姆视为出色工匠与材料研究者，即使他们未必接受过现代科学教育。经验、制作技艺与正式学术之间，可以存在不同传承路径。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·匹特拉姆（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1180—1187行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·匹特拉姆（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1180—1187行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"anaty","name":"阿纳缇","en":"Anaty","summary":"山地行走、信使工作和依山而建的居所，体现了环境与生活技术之间的联系。","relatedRegions":["kjerag","yan"],"profileNames":["阿纳缇"],"relatedNames":[],"sourceLines":[1188,1200],"sections":[{"title":"山地生活与交通工作","period":"传统山区生活至移动城市时代","body":"阿纳缇与山地生活关系密切。许多社群长期居住在远离平原的山区，擅长在崎岖地形中奔走，也热情接待来客。这种交通经验使部分人从事行商和信使，把分散定居点之间的往来变成日常职业。\n\n移动城市发展以后，工作范围从山地延伸到新的城市网络。技能的使用地点发生变化，原来辨路、运输和沟通的经验却并未因此失去作用。书中在这里描述的是职业活动的转移。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·阿纳缇（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1188—1200行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"居住技术与成年习俗","period":"部分偏远聚落的传统","body":"仍住在山中的社群，善于沿山体开凿洞穴式居所。其建造更多依靠挖掘与利用原有地形，形成与地表建筑不同的居住系统。住房方式与地形、施工经验及长久定居相互关联。\n\n部分偏远社群保存严格的成年礼：年轻人在荒山野岭独立生活一段时间，学习在外部支援有限时应对环境。这类做法在外人看来严苛，却体现当地传授生存技能的方式。设定集将其限定为部分社群的传统。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·阿纳缇（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1188—1200行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·阿纳缇（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1188—1200行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"pilosa","name":"皮洛萨","en":"Pilosa","summary":"公开材料稀少，认识这一族群尤其需要分清现场记录、艺术作品与个体见闻。","relatedRegions":["rim","higashi"],"profileNames":["皮洛萨"],"relatedNames":[],"sourceLines":[1201,1214],"sections":[{"title":"有限材料与分类困难","period":"长久零散记载至当代调查","body":"皮洛萨是本章资料最少的族群之一。作者承认自己没有亲眼见过，又很少获得能够持续核对的见闻，因此只保留历史文献中的记录，没有据传闻为整个族群建立详尽的形貌与生活模型。\n\n1053年7月的一则矿场安全记录，留下了利亚姆·麦克林的具体经历：他因违反安全生产规定将被罚款，试图进入管理设施删除违规记录，翻越铁丝网时被困，随后由管理人员带走。记录最终说明其被转交后勤重新分配工作，罚款并未取消。这是一个劳动现场中的个案。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·皮洛萨（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1201—1214行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"艺术形象与现实人物","period":"1053年记录及1086年出版物以后","body":"另一则材料来自1086年出版的东国漫画。作品把受到轻视的迟缓者写成剑豪，以缓慢动作和独特剑意塑造反转。这能够说明皮洛萨形象怎样进入大众文艺。\n\n转录中的罗德岛人事批注又将稀音与皮洛萨身份联系起来，但字句存在明显残损。安全报告、漫画与正式档案在这里各司其职：前者留下具体事件，中者保存艺术形象，后者用于定位实际人物。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·皮洛萨（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1201—1214行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·皮洛萨（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1201—1214行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"draco","name":"德拉克","en":"Draco","summary":"神话中的强大统治者与现实中的分散家系之间，存在需要逐一辨认的历史层次。","relatedRegions":["victoria","sargon"],"profileNames":["德拉克"],"relatedNames":[],"sourceLines":[1221,1226],"sections":[{"title":"分散家系与王权历史","period":"远古统治传统至维多利亚王权","body":"德拉克人数稀少，分散在不同地区，却在古代统治史和传说中占据显著位置。维多利亚王权是其中能够与国家沿革相互对照的一条线索；塔拉盖尔王家与伦蒂尼姆分享王权的龙之家族，又各有自身关系，不能因同一统称就混为一个没有差别的家系。\n\n德拉克这个统称的认同曾经相当松散。设定集认为，核心圈直到近千年才逐渐以同一名称概括这些有共同特点的群体。此前按地域流传的称号、习俗与故事，使他们的形象既相似又彼此有别。\n\n现代接触和研究能够确认某些身体与源石技艺方面的优势。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·德拉克（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1221—1226行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"统称形成与个体经历","period":"近千年的分类与交流","body":"关于掠夺者、藏宝王和不死红龙的故事，在许多人真正见过德拉克以前就已流传。它们有的借统治者的财富和暴力传述历史，有的成为吓唬儿童的传说，甚至把无需源石技艺飞行、喷火的形象也附着其上。作者特意把这些说法与当时所知区分开来。\n\n因此，德拉克形象的影响范围远大于真实人口分布。一个现代人物可能因名字、家系和外观被外界赋予政治期待，其本人却未必掌握或认同传说中的权力。维多利亚和塔拉的具体历史，能够解释这种期待为什么持续存在。\n\n不同家系对王权的记忆，又会通过战争、宫廷和流亡进入个人生活。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·德拉克（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1221—1226行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·德拉克（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1221—1226行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"lung","name":"龙","en":"Lung","summary":"炎氏、百氏与文字保存传统，构成炎国龙族认识自身历史的重要线索。","relatedRegions":["yan","lungmen"],"profileNames":["龙"],"relatedNames":[],"sourceLines":[1231,1237],"sections":[{"title":"炎氏与百氏后代","period":"炎国早期建制及其后","body":"龙主要生活在炎国，其认同与共同祖先炎氏及早期国家形成相连。炎氏带领部族抵御灾害、整合不同社群，又以文字、赐姓和土地安排建立联系，后来的百氏由此把共同政治秩序记入家族来源。\n\n真龙一族指向皇室，但炎国还有许多非皇族的龙。书中特意解释，真并非用来指责其他同族是假，而是对共同祖先与传奇领袖的尊称。族名、皇室资格和朝廷职位是相连而不同的身份。\n\n这使龙的历史不只是一部皇帝名录。普通家族通过姓氏、家传与公共文书保存来源，国家也把这些记忆纳入自己的历史书写之中，形成相互支撑的认同。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·龙（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1231—1237行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"文书传统与翻译差异","period":"长期史书编纂及对外交流","body":"炎国设有收集、编纂与保存历史的机构，《封龙纪》《百姓考》《百家通历》等文献又进入指定档案馆。相对于主要靠口头传承的起源故事，作者据此认为龙的历史留下了更详尽的文书线索；这仍是对材料条件的比较。\n\n早期国际交往中，维多利亚翻译者曾借用龙这个炎国字介绍德拉克君主。称呼传播以后，炎国一度以为西方也生活着同类。后来交流扩大、差异得到确认，德拉克才成为正式译称，部分习惯名称却继续留下。\n\n这一误译把两段不同的历史暂时叠在同一个词上。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·龙（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1231—1237行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·龙（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1231—1237行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"kylin","name":"麒麟","en":"Kylin","summary":"炎国的术法教育与司法传统，保存了多个麒麟家族参与公共事务的历史。","relatedRegions":["yan"],"profileNames":["麒麟"],"relatedNames":[],"sourceLines":[1244,1248],"sections":[{"title":"早期侍卫与术法传承","period":"炎氏部族时期及后来的天师教育","body":"麒麟人口不多，在炎国的政治与社会生活中却享有较高威望。书中把其与炎氏部族的合作追溯到百氏之乱以前，当时已有麒麟担任侍卫和术师。关于雷池的故事，则把一名术师驱退害兽的行动，保存在长期流传的地名与俗语中。\n\n传说中，术师让雷霆从湖中生发，使害兽不敢越过。湖泊位置到后来已经无法考证，但招引雷电的技艺有后续传承。传说的地理细节和可追踪的技艺谱系，在这里属于不同层次的材料。\n\n这位术师的后人以祖先职业祝为姓，形成祝氏麒麟。家族掌握技艺与承担朝廷职责的关系，也使知识传承带有明确的社会组织背景。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·麒麟（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1244—1248行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"家系、司法与个人责任","period":"历代朝廷至现代公共事务","body":"真龙设立天师府以后，祝氏后人成为早期授业者之一，奉命将雷法教授给有才能的弟子。原来主要留在家系内部的知识，由此进入更广泛的教育体系，不再限于祝氏或麒麟。家传技艺通过天师府获得新的学习和传授渠道。\n\n麒麟也并非都出自祝氏。麟氏、法氏等家族与朝廷保持联系，历史上常有人负责法律、惩戒与地方秩序。长期的职务传统，使麒麟在民间逐渐成为护佑一方平安的象征。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·麒麟（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1244—1248行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·麒麟（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1244—1248行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"aegir","name":"阿戈尔","en":"Ægir","summary":"从海岸到内陆水体的迁徙，留下复杂而多样的族群；同名文明与每个人的国籍并非一回事。","relatedRegions":["aegir","iberia","higashi"],"profileNames":["阿戈尔"],"relatedNames":[],"sourceLines":[1249,1260],"sections":[{"title":"分布与水体依赖","period":"历史迁徙至陆地定居","body":"阿戈尔居民分布在海岸和内陆水体附近，内部支系众多，身体适应性也各不相同。设定集记录过能够在水下呼吸的个体，同时强调多数受访者并不具备这一能力。阿戈尔内部的水下生活能力与习惯因支系而有差别。\n\n在陆地生活时，他们对水分的需求具体体现在呼吸道、皮肤和失水后的身体反应。河湖与海岸提供了较适宜的居住环境，进入干旱地区则需要额外准备。选择住所、安排旅程和携带装备，因此成为迁居经验的一部分。\n\n作者看到的地方传说包括伊比利亚岛民对海中国度的讲述，以及东国的相关神话。它们与由外沿向内陆分布的图景相呼应，但在本章的认识范围内，海洋起源仍以研究者的推断呈现。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·阿戈尔（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1249—1260行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"陆地生活与适应技术","period":"长期陆居及现代生活","body":"为了在陆地保持身体水分，部分阿戈尔使用保湿霜剂；深入沙漠时还会携带特殊蒸馏设备，在途中取得供水。这类装备也被其他沙漠居民学习使用，个体的适应办法因而成为跨社群技术交流的一部分。\n\n种族身份与海中国家的政治归属并不等同。一个居住在地上的阿戈尔，可能只熟悉家乡和当地机构，并未进入过海下城市。\n\n地区纪事另以海嗣威胁、城市计划与战争动员展开海下文明的历程。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·阿戈尔（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1249—1260行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·阿戈尔（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1249—1260行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"sankta","name":"萨科塔","en":"Sankta","summary":"律法、共感与圣城公民生活紧密相连，理解能力边界同样重要。","relatedRegions":["laterano"],"profileNames":["萨科塔"],"relatedNames":[],"sourceLines":[1261,1265],"sections":[{"title":"律法与共感生活","period":"拉特兰长期形成的共同生活","body":"萨科塔的光环与光翼在设定集中被解释为受到律法庇护的象征，其社会生活长期围绕拉特兰展开。共感是这一联系最特殊的经验之一：萨科塔在日常交往中会自然地感知彼此，未必把它当作每次都需要主动启动的技术。\n\n作者以其他人观察表情作比，尝试向非萨科塔读者说明这种经验，同时承认比喻不能完整复制共感的感受。共同情绪和反应使圣城内形成某些默认的理解方式，也让缺乏同样经验的居民面对不同的交往处境。\n\n共感与律法共同参与了圣城的社会生活。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·萨科塔（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1261—1265行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"守护铳与社会实践","period":"信仰传统及现代成长","body":"守护铳在萨科塔社会中不只是武器，也是信仰与个人成长的重要物件。设定集说明，没有一条要求人人必须持有守护铳的普遍规章，但拉特兰适龄萨科塔普遍拥有自己的铳，个人在文化中接受它，往往先于为这一习惯寻找明确的命令来源。\n\n这使训练、携带和使用铳械嵌入家庭与城市生活。学校、修道院和公共制度提供知识与规范，个人又在长期使用中与自己的守护铳建立关系。把它只写成一种天生装备，会略去学习、保管与责任的实际过程。\n\n离开圣城的人仍可能带着这套经验进入别国，也会面对共感无法替代的沟通和制度差异。拉特兰人物纪事中的外勤、合作与旧案，分别记录这些人在具体环境下如何理解并承担自己的身份。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·萨科塔（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1261—1265行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·萨科塔（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1261—1265行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"id":"sarkaz","name":"萨卡兹","en":"Sarkaz","summary":"提卡兹的家园记忆、长期流亡和多支氏族的差异，使萨卡兹无法被一个外貌或性格概括。","relatedRegions":["kazdel","sami","sargon"],"profileNames":["萨卡兹","鬼","阿纳萨"],"relatedNames":[],"sourceLines":[1275,1292],"sections":[{"title":"家园、流亡与多重氏族","period":"古代提卡兹历史至长期离散","body":"萨卡兹内部的形貌与氏族差异很大。设定集既提到作为近代卡兹戴尔重要基础的十王庭，也列出歌利亚、阿纳萨、鬼等非王庭群体；多数萨卡兹又具有不同氏族交融的来源。氏族交融与非王庭群体共同构成萨卡兹的人口。\n\n族群的自述把过去追溯到提卡兹和失落家园。此后反复毁城、战争与迁徙，使氏族分散，也使许多家庭不得不在其他国家或荒野寻找生存条件。卡兹戴尔的政治重建，始终与这些散居者能否重新拥有家园的问题相连。\n\n长久动荡又削弱共同组织，王庭之间并不总能一致行动。共同称谓可以保存历史认同，却不会自动消除家系、地区和政治选择的分歧；特蕾西娅与特雷西斯周围不同人员的道路，便发生在这样的历史之中。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·萨卡兹（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1275—1292行；印刷页范围据目录，未据原版影印逐页校勘。"}]},{"title":"偏见、疾病与文化流失","period":"长期流亡至现代社会","body":"外界长期把暴力、危险和野蛮等负面特征强加给萨卡兹，并以这些判断为战争与排斥辩护。流亡者又常不向外人解释自身传统，文化失去传承场所和记录者之后，一部分知识便悄然消失。现代雇佣兵的普遍形象，也与长期漂泊和谋生条件有关。\n\n矿石病进一步改变个人与社群的生活。书中记下较易感染的观察，也分别列出关于源石适应性、血脉技艺与古老诅咒的不同解释，并未把它们归成一项已经证实的统一病因。治疗和研究需要面对实际身体状况。\n\n共同苦难可以促成合作，战时立场也可能使旧同伴分离。追踪这些具体关系，才能看到萨卡兹如何在被概括的历史之外，继续组织自己的生活。","refs":[{"label":"《大地巡旅》第四章“泰拉种族”·萨卡兹（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1275—1292行；印刷页范围据目录，未据原版影印逐页校勘。"}]}],"sources":[{"label":"《大地巡旅》第四章“泰拉种族”·萨卡兹（印刷页079—106）","url":"#/sources/reference/journey-races","evidence":"journey","note":"用户提供TXT转录，第1275—1292行；印刷页范围据目录，未据原版影印逐页校勘。"}]}]};
